create function pg_temp.assert_test(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"03000000-0000-4000-8000-000000000002","session_id":"13000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
do $test$ declare a jsonb;b jsonb;input jsonb;r jsonb;client uuid:='83000000-0000-4000-8000-000000000001';aid uuid;req uuid:=gen_random_uuid();denied boolean:=false;begin
 r:=public.attempt_command(jsonb_build_object('action','start','exam_id','53000000-0000-4000-8000-000000000001','client_id',client,'pin','000000'));perform pg_temp.assert_test(r->>'error'='PIN tidak valid','bad PIN rejected');
 a:=public.attempt_command(jsonb_build_object('action','start','exam_id','53000000-0000-4000-8000-000000000001','client_id',client,'pin','887766'));aid:=(a->>'id')::uuid;perform set_config('test.attempt',aid::text,true);perform set_config('test.deadline',a->>'deadline_at',true);
 perform pg_temp.assert_test(jsonb_array_length(a->'questions')=5,'five snapshot questions');perform pg_temp.assert_test(private.can_upload_attempt_canvas('03000000-0000-4000-8000-000000000002/'||aid::text||'/63000000-0000-4000-8000-000000000005/test.png'),'canvas upload bound to live essay snapshot');perform pg_temp.assert_test(not private.can_upload_attempt_canvas('03000000-0000-4000-8000-000000000002/'||aid::text||'/63000000-0000-4000-8000-000000000001/test.png'),'PG does not allow canvas upload');perform pg_temp.assert_test(not(a->'questions'->0->'payload' ? 'key') and a::text not like '%Secret rubric%' and a::text not like '%Secret explanation%' and a::text not like '%pin_hash%','no keys/rubric/explanation/hash in student DTO');
 b:=public.attempt_command(jsonb_build_object('action','resume','attempt_id',aid,'client_id',client));perform pg_temp.assert_test(a->'questions'=b->'questions' and a->>'deadline_at'=b->>'deadline_at','stable snapshot shuffle and deadline');
 b:=public.attempt_command(jsonb_build_object('action','start','exam_id','53000000-0000-4000-8000-000000000001','client_id',client,'pin','887766'));perform pg_temp.assert_test(a->>'id'=b->>'id','no duplicate attempt');
 begin perform public.attempt_command(jsonb_build_object('action','submit','attempt_id',aid,'client_id',client,'epoch',1,'request_id',gen_random_uuid(),'mode','manual'));exception when others then denied:=sqlerrm like 'REQUIRED:%';end;perform pg_temp.assert_test(denied,'manual requires required answers');
 input:=jsonb_build_object('action','save','attempt_id',aid,'client_id',client,'epoch',1,'request_id',req,'answers','[{"question_id":"63000000-0000-4000-8000-000000000001","expected_revision":0,"value":["A"]},{"question_id":"63000000-0000-4000-8000-000000000002","expected_revision":0,"value":["A"]},{"question_id":"63000000-0000-4000-8000-000000000003","expected_revision":0,"value":{"s1":"true","s2":"true"}},{"question_id":"63000000-0000-4000-8000-000000000004","expected_revision":0,"value":{"j1":"Right1","j2":"Right1"}},{"question_id":"63000000-0000-4000-8000-000000000005","expected_revision":0,"value":{"text":"Essay answer"}}]'::jsonb);
 r:=public.attempt_command(input);perform pg_temp.assert_test(jsonb_array_length(r->'acknowledgements')=5,'persistent batch ACK');perform pg_temp.assert_test(public.attempt_command(input)=r,'retry same request ACK');
 b:=public.attempt_command(jsonb_set(input,'{request_id}',to_jsonb(gen_random_uuid())));perform pg_temp.assert_test(b->'acknowledgements'->0->>'error'='CONFLICT','stale revision does not overwrite');
 denied:=false;begin perform public.attempt_command(jsonb_set(input,'{answers,0,value}','["B"]'));exception when others then denied:=sqlerrm like 'IDEMPOTENCY_CONFLICT:%';end;perform pg_temp.assert_test(denied,'request key payload conflict');
 denied:=false;begin perform public.attempt_command(jsonb_build_object('action','resume','attempt_id',aid,'client_id','83000000-0000-4000-8000-000000000002'));exception when others then denied:=sqlerrm like 'DEVICE_CONFLICT:%';end;perform pg_temp.assert_test(denied,'second device requires explicit takeover');
 b:=public.attempt_command(jsonb_build_object('action','takeover','attempt_id',aid,'client_id','83000000-0000-4000-8000-000000000002'));perform pg_temp.assert_test(b->>'epoch'='2' and b->>'deadline_at'=a->>'deadline_at','takeover writer epoch, same deadline');
 denied:=false;begin perform public.attempt_command(jsonb_set(input,'{request_id}',to_jsonb(gen_random_uuid())));exception when others then denied:=sqlerrm like 'DEVICE_CONFLICT:%';end;perform pg_temp.assert_test(denied,'old device cannot overwrite');
 for input in select jsonb_build_object('action','event','attempt_id',aid,'client_id','83000000-0000-4000-8000-000000000002','epoch',2,'event_id','93000000-0000-4000-8000-000000000001','kind','visibility_hidden','duration_ms',2000,'editing',false,'orientation_recent',false) loop perform public.attempt_command(input);perform public.attempt_command(input);end loop;
 b:=public.attempt_command(jsonb_build_object('action','resume','attempt_id',aid,'client_id','83000000-0000-4000-8000-000000000002'));perform pg_temp.assert_test(b->>'status'='in_progress','no automatic DQ');
end $test$;
