do $$declare denied boolean:=false;begin begin perform public.review_attempt(jsonb_build_object('action','unlock','attempt_id',current_setting('test.attempt'),'reason','Not authorized supervisor'));exception when others then denied:=sqlerrm like 'AUTH:%';end;perform pg_temp.assert_test(denied,'unassigned teacher cannot unlock');end$$;
