do $$declare a jsonb;r jsonb;begin a:=public.attempt_command(jsonb_build_object('action','start','exam_id','53000000-0000-4000-8000-000000000002','client_id','83000000-0000-4000-8000-000000000001','pin','887766'));perform set_config('test.timeout',a->>'id',true);end$$;
