do $$declare r jsonb;begin r:=public.attempt_command(jsonb_build_object('action','resume','attempt_id',current_setting('test.timeout'),'client_id','83000000-0000-4000-8000-000000000001'));perform pg_temp.assert_test(r->>'status'='time_expired' and (r->>'score')::numeric=0 and r->>'result_visible'='true','timeout ignores required, official zero is distinct from pending');end$$;
