do $$declare r jsonb;i int;limited boolean:=false;begin for i in 1..11 loop r:=public.attempt_command(jsonb_build_object('action','start','exam_id','53000000-0000-4000-8000-000000000002','client_id','83000000-0000-4000-8000-000000000001','pin','000000'));if r->>'status'='429' then limited:=true;end if;end loop;perform pg_temp.assert_test(limited,'bad PIN budget persists across failure responses');end$$;
